"""Curated, incremental A1/A2 lessons. No model calls or learner-state writes.

Each teaching card precedes its own exercise. Stable lesson/task IDs remain;
changed tasks get a new revision. Run once to publish the reviewed source below.
"""
import json
import hashlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
COURSE = ROOT / 'content/courses/foundation.json'
LESSONS = []

def write_json(path, data):
    ending = '\r\n' if b'\r\n' in path.read_bytes() else '\n'
    path.write_bytes((json.dumps(data,ensure_ascii=False,indent=2)+'\n').replace('\n',ending).encode('utf-8'))

def unit(id, title, goal, blocks, independent):
    LESSONS.append((id, title, goal, blocks, independent))

def block(title, body, model, translation, *tasks):
    return (title, body, model, translation, tasks)

def task(prompt, answer, why):
    return (prompt, answer, why)

unit('path-be', 'Я, ты, он: зачем нужны am, is и are', 'Сказать, кто ты и как себя чувствуешь. Начинаем с трёх слов.', [
 block('Почему не просто I ready?', 'По-русски можно сказать «Я готов». По-английски между «я» и «готов» нужно am: I am ready. I значит «я», ready — «готов». Am не нужно переводить отдельным словом. Оно помогает собрать эту английскую фразу. I всегда пишется с большой буквы.', 'I am ready.', 'Я готов.',
  task('Скажи «Я устал». Используй I am; tired = устал. Напиши три слова.', 'I am tired.', 'I — я, am — нужная форма после I, tired — устал. Ничего добавлять не нужно.'),
  task('Теперь скажи «Я счастлив». happy = счастлив. Начни с I.', 'I am happy.', 'После I оставляем am. Меняется только последнее слово.')),
 block('You — ты или вы', 'You значит и «ты», и «вы». После you ставим are, а не am. Слова ready, tired и happy уже знакомы: теперь расскажем о другом человеке.', 'You are ready.', 'Ты готов. / Вы готовы.',
  task('Скажи человеку «Ты устал».', 'You are tired.', 'You are — готовая пара. Tired не меняется.'),
  task('Скажи «Вы счастливы».', 'You are happy.', 'И к одному человеку, и к нескольким обращаемся you are.')),
 block('He, she, it — он, она, это', 'He — он, she — она. It используем, например, для вещи: «это». После всех трёх ставим is. Is делает ту же работу, что am и are, но подходит к he, she, it.', 'She is ready.', 'Она готова.',
  task('Скажи «Он устал». he = он.', 'He is tired.', 'С he нужна форма is.'),
  task('Устройство готово к работе. Скажи коротко «Оно готово», начиная с It.', 'It is ready.', 'Для устройства здесь подходит it; после него ставим is.')),
 block('We и they — мы и они', 'We — мы, they — они. С обоими словами нужна форма are. Получается: I am; he/she/it is; you/we/they are. Эту схему будем много раз применять, заучивать всё за один раз не требуется.', 'We are happy.', 'Мы счастливы.',
  task('Скажи «Они готовы». they = они.', 'They are ready.', 'They сочетается с are.')),
 block('Как сказать «не»', 'Not значит «не». Поставь его после am, is или are. Остальные слова остаются на своих местах.', 'I am not tired.', 'Я не устал.',
  task('Скажи «Она не готова».', 'She is not ready.', 'Сначала she is, затем not, затем ready.')),
 block('Как спросить', 'Чтобы спросить «Ты готов?», поменяй местами you и are. Получится Are you ready? В конце поставь вопросительный знак. Нового слова для вопроса здесь не нужно.', 'Are you ready?', 'Ты готов?',
  task('Спроси «Она устала?»', 'Is she tired?', 'В вопросе is стоит перед she.')),
 block('Почему в речи слышно I’m', 'I am часто сокращают до I’m. Это то же самое по смыслу. Апостроф ’ показывает место пропущенной буквы. You are → you’re; she is → she’s. Полная форма тоже правильная.', 'I’m happy.', 'Я счастлив.',
  task('Напиши «Я готов» с сокращением I’m.', "I'm ready.", 'I’m и I am — два варианта одной формы.'))
], [task('Напиши одну правдивую фразу о себе: ready, tired или happy. Можно добавить not. Только одно предложение.', 'I am not tired.', 'Выбери своё состояние. Подходит любая верная фраза с I am, а не только этот пример.'), task('Спроси друга, готов ли он. Затем отдельной фразой скажи, что ты готов.', 'Are you ready? I am ready.', 'Сначала вопрос Are you, затем ответ о себе I am. Это вся задача.')])

unit('path-articles-basic', 'A, an, the: о какой вещи говорим', 'Назвать одну вещь и показать, когда собеседник уже понимает, какую.', [
 block('A — одна вещь такого типа', 'Book — книга. Когда называем одну книгу, говорим a book. Маленькое a показывает: речь об одном предмете, а не о книгах вообще. По-русски отдельного слова часто нет. It is значит «Это».', 'It is a book.', 'Это книга.', task('Назови предмет: «Это ручка». pen = ручка.', 'It is a pen.', 'Pen называет одну вещь, поэтому здесь a pen.'), task('Скажи «Он учитель». teacher = учитель.', 'He is a teacher.', 'Профессия тоже называет одного представителя группы: a teacher.')),
 block('An — тот же смысл, удобнее произнести', 'Перед гласным звуком вместо a говорим an: an apple. Выбираем по звуку, а не просто по букве. Пока потренируем понятные слова: apple — яблоко, egg — яйцо.', 'It is an apple.', 'Это яблоко.', task('Скажи «Это яйцо».', 'It is an egg.', 'Egg начинается с гласного звука: an egg.'), task('Скажи «Она актриса». actor = актёр или актриса.', 'She is an actor.', 'Actor начинается с гласного звука, поэтому an.')),
 block('The — понятно, какая именно вещь', 'Сначала можно назвать a book: какую-то книгу. Когда говорим об этой уже известной книге, используем the book. Red значит «красная». Не переводи the автоматически как «этот»: его работа — показать, что вещь уже можно определить.', 'It is a book. The book is red.', 'Это книга. Книга красная.', task('Ты уже назвал одну ручку. Скажи, что эта ручка синяя. blue = синяя.', 'The pen is blue.', 'Собеседник знает, о какой ручке речь: the pen.'), task('Перепиши правильно: It is a apple.', 'It is an apple.', 'Перед звуком в начале apple нужна форма an.'))
], [task('Назови одну книгу и скажи, что она синяя. Два коротких предложения.', 'It is a book. The book is blue.', 'Сначала вводим книгу с a, затем говорим о ней с the.'), task('Назови по-английски один предмет: книгу, ручку, яблоко или яйцо. Начни с It is.', 'It is an apple.', 'Выбери a или an по следующему звуку. Можно назвать любой из четырёх предметов.')])

unit('path-plurals', 'Один предмет и несколько: book → books', 'Назвать несколько предметов и согласовать с ними are.', [
 block('Добавляем -s', 'One — один, two — два, three — три. Одна книга — one book, две — two books. Обычно к названию нескольких предметов добавляем -s. Перед несколькими предметами a/an не ставим.', 'Two books.', 'Две книги.', task('Напиши «три ручки». pen = ручка.', 'Three pens.', 'После three нужна форма pens.'), task('Напиши «два яблока». apple = яблоко.', 'Two apples.', 'An относится к одному предмету. Здесь two apples.')),
 block('Иногда -es или -ies', 'После -s, -sh, -ch, -x обычно добавляем -es: box → boxes. После согласной + y меняем y на ies: baby → babies. Box — коробка, baby — малыш. После гласной + y просто -s: toy → toys.', 'Two boxes.', 'Две коробки.', task('Напиши «три малыша».', 'Three babies.', 'В baby перед y стоит согласная b: y заменяется на ies.'), task('Напиши «две игрушки». toy = игрушка.', 'Two toys.', 'Перед y стоит гласная o, поэтому просто добавляем s.')),
 block('Несколько предметов — are', 'Если говорим о нескольких вещах, используем are. The books are blue — книги синие. Есть особые формы: child → children (ребёнок → дети), person → people (человек → люди). Их запоминаем как отдельные пары.', 'The books are blue.', 'Книги синие.', task('Скажи «Дети готовы». children = дети.', 'The children are ready.', 'Children — несколько детей, поэтому are.'), task('Исправь: The pens is red.', 'The pens are red.', 'Pens — несколько ручек; is заменяем на are.'))
], [task('Напиши «два человека».', 'Two people.', 'Обычная форма для нескольких людей — people.'), task('Представь две красные коробки. Скажи, что коробки красные, одним предложением.', 'The boxes are red.', 'Boxes — несколько коробок, поэтому are.')])

unit('path-pronouns', 'I, me, my: кто, кому и чей', 'Различать «я», «мне» и «мой» в коротких фразах.', [
 block('Кто делает — I, he, she', 'Когда человек сам делает действие, называем его I, you, he, she, we или they. Know значит «знать». I know — я знаю. После he и she добавляем -s, как с work в прошлом уроке: he knows — он знает.', 'I know Alex.', 'Я знаю Алекса.', task('Скажи «Я знаю Мию». Mia — имя.', 'I know Mia.', 'I стоит перед действием: я знаю.'), task('Скажи «Они готовы», заменив «они» английским словом.', 'They are ready.', 'Здесь they называет тех, о ком мы сообщаем.')),
 block('Кого — me, him, her', 'Когда действие направлено на человека, нужна другая форма: me — меня/мне, him — его/ему, her — её/ей, us — нас/нам, them — их/им. You не меняется. I know her — я знаю её.', 'You know me.', 'Ты знаешь меня.', task('Скажи «Я знаю его».', 'I know him.', 'После know здесь him, потому что речь о том, кого ты знаешь.'), task('Скажи «Ты знаешь их».', 'You know them.', 'Them значит «их».')),
 block('Чья вещь — my, your, his, her', 'Перед названием вещи ставим слово «чей»: my — мой, your — твой/ваш, his — его, her — её, our — наш, their — их. После my уже не нужно a или the: my book.', 'My book is blue.', 'Моя книга синяя.', task('Скажи «Её ручка красная».', 'Her pen is red.', 'Her перед pen показывает, чья это ручка.'), task('Исправь: My a book is blue.', 'My book is blue.', 'My уже определяет книгу. Дополнительное a убираем.'))
], [task('Скажи двумя фразами: «Это моя книга. Она синяя». Для книги используй it.', 'It is my book. It is blue.', 'My показывает владельца, it заменяет повторное название вещи.'), task('Напиши «Я знаю её. Её книга красная».', 'I know her. Her book is red.', 'В первой фразе her — кого знаю, во второй — чья книга.')])

unit('path-present-simple', 'Что я делаю обычно: I work', 'Рассказать о привычке, сказать «не» и задать простой вопрос.', [
 block('Действие вместо am/is/are', 'Work — работать, live — жить, like — любить/нравиться. В I work уже есть действие. Добавлять am не нужно: I work, а не I am work. Так говорим о привычках и обычной жизни.', 'I work here.', 'Я работаю здесь.', task('Скажи «Я живу здесь». live = жить, here = здесь.', 'I live here.', 'Live уже является действием: am не добавляем.'), task('Скажи «Она работает здесь». Для she добавь -s к work.', 'She works here.', 'С he, she, it в утверждении добавляем -s: works.')),
 block('Don’t и doesn’t — не делаю', 'Для «не» перед действием ставим don’t. С he/she/it ставим doesn’t. После doesn’t действие снова без -s: she doesn’t work. Don’t — сокращение do not, doesn’t — does not.', "I don't work here.", 'Я здесь не работаю.', task('Скажи «Я не люблю кофе». like = любить, coffee = кофе.', "I don't like coffee.", 'Don’t стоит перед like. Coffee здесь — кофе вообще.'), task('Скажи «Она здесь не живёт».', "She doesn't live here.", 'После doesn’t используем live без -s.')),
 block('Do и does — вопрос о действии', 'Перед I/you/we/they в вопросе ставим do. Перед he/she/it — does. Сам глагол остаётся без -s. Do здесь помогает спросить, отдельно как «делать» его не переводим.', 'Do you work here?', 'Ты здесь работаешь?', task('Спроси «Она здесь живёт?»', 'Does she live here?', 'Does перед she, затем live без -s.'), task('Спроси «Ты любишь кофе?»', 'Do you like coffee?', 'Для you нужна вопросительная форма Do you.'))
], [task('Сообщи о себе одну привычку с like: tea = чай, coffee = кофе. Можно отрицание.', 'I like tea.', 'Твой выбор может отличаться. Нужна фраза I like или I don’t like.'), task('Скажи «Он здесь работает?» и затем «Он здесь не работает».', "Does he work here? He doesn't work here.", 'В обоих случаях work без -s: does и doesn’t уже показывают he.')])

unit('path-possession', 'У меня есть: have и has', 'Рассказать о своих вещах и их владельцах.', [
 block('Have — у меня есть', 'Have значит «иметь», но по-русски обычно говорим «у меня есть». I have a phone — у меня есть телефон. После he/she/it нужна форма has.', 'I have a phone.', 'У меня есть телефон.', task('Скажи «У меня есть книга».', 'I have a book.', 'Have сообщает о том, что у тебя есть.'), task('Скажи «У неё есть телефон». phone = телефон.', 'She has a phone.', 'С she нужна форма has.')),
 block('Отрицание и вопрос уже знакомы', 'Have здесь ведёт себя как work: I don’t have; Does she have? После doesn’t или does используем have, а не has. Это обычная американская формулировка.', "I don't have a car.", 'У меня нет машины.', task('Спроси «У тебя есть машина?» car = машина.', 'Do you have a car?', 'Do you + have — вопрос о том, что у тебя есть.'), task('Скажи «У него нет телефона».', "He doesn't have a phone.", 'Doesn’t + have, не doesn’t has.')),
 block('Alex’s — Алекса', 'Чтобы назвать владельца, добавь к имени ’s: Alex’s book — книга Алекса. Здесь ’s показывает владельца, а не сокращает is. После названия вещи можно поставить is.', "Alex's book is red.", 'Книга Алекса красная.', task('Скажи «Телефон Мии синий». Mia — имя.', "Mia's phone is blue.", 'Mia’s показывает владельца телефона.'), task('Напиши «книга моего друга». friend = друг; my friend → my friend’s.', "My friend's book.", '’s ставится после владельца friend.'))
], [task('Напиши одну фразу о вещи, которая у тебя есть или которой нет.', 'I have a phone.', 'Можно выбрать знакомую вещь и отрицание. С I используем have.'), task('Спроси друга, есть ли у него книга, одним предложением.', 'Do you have a book?', 'Для have задаём вопрос с do.')])

unit('path-questions-basic', 'Что, где и кто: короткие вопросы', 'Выбрать начало вопроса, не смешивая be и do.', [
 block('Where — где', 'Where значит «где». Если дальше am/is/are, ставим вопросительное слово перед ними. You are here → Where are you? Для вопроса о месте не нужно добавлять do.', 'Where are you?', 'Где ты?', task('Спроси «Где она?»', 'Where is she?', 'Where, затем is, затем she.'), task('Спроси «Где моя книга?»', 'Where is my book?', 'Книга одна: is my book.')),
 block('Вопрос о действии', 'Для work, live и других действий сохраняем do/does. Where do you live? — где ты живёшь? What — что; when — когда. What do you like? — что тебе нравится?', 'Where do you work?', 'Где ты работаешь?', task('Спроси «Где он живёт?»', 'Where does he live?', 'С he берём does; live остаётся без -s.'), task('Спроси «Что тебе нравится?»', 'What do you like?', 'What + do you + like.')),
 block('Who — кто', 'Who is she? — кто она? А в Who works here? слово who само обозначает того, кто работает. Поэтому обычный вопрос «Кто здесь работает?» не требует do. Это два разных образца.', 'Who is she?', 'Кто она?', task('Спроси «Кто здесь живёт?» Используй who вместо имени человека.', 'Who lives here?', 'Who само занимает место человека: lives.'), task('Исправь: Where do you are?', 'Where are you?', 'С are не нужен помощник do.'))
], [task('Задай два вопроса: где человек сейчас и где он работает. Обращайся на you.', 'Where are you? Where do you work?', 'Состояние/место — are; действие work — do.'), task('Спроси, что нравится твоему другу, и ответь за себя одной фразой с like.', 'What do you like? I like tea.', 'Ответ выбирай свой. Вопрос начинается с What do you.')])

unit('path-present-continuous', 'Делаю прямо сейчас: I am working', 'Отличить действие сейчас от привычки.', [
 block('Сейчас в процессе', 'I work — работаю вообще. I am working — работаю прямо сейчас или в текущий период. Здесь нужны две части: am/is/are и действие с -ing. Work → working, read → reading.', 'I am reading.', 'Я сейчас читаю.', task('Скажи «Я сейчас работаю».', 'I am working.', 'Am + working показывают процесс сейчас.'), task('Скажи «Она сейчас читает».', 'She is reading.', 'С she выбираем is, затем reading.')),
 block('Не происходит? Или спросим?', 'Отрицание: поставь not после am/is/are. Вопрос: перенеси am/is/are перед человеком. Do не добавляем — вопрос строится как уже знакомый вопрос с be.', 'Are you working?', 'Ты сейчас работаешь?', task('Скажи «Он сейчас не работает».', 'He is not working.', 'Not стоит между is и working.'), task('Спроси «Они сейчас читают?»', 'Are they reading?', 'Are перед they, затем reading.')),
 block('Обычно и сейчас', 'Every day — каждый день; now — сейчас. Сравни I work every day и I am working now. Эти слова помогают понять смысл, но выбираем форму по ситуации: привычка или процесс. Write → writing: перед -ing немая e исчезает.', 'I write every day. I am writing now.', 'Я пишу каждый день. Сейчас я пишу.', task('Скажи «Она работает каждый день».', 'She works every day.', 'Обычная привычка: works.'), task('Скажи «Она сейчас пишет».', 'She is writing now.', 'Сейчас процесс: is writing; write теряет конечную e.'))
], [task('Напиши две фразы: «Я читаю каждый день. Я сейчас читаю».', 'I read every day. I am reading now.', 'Один и тот же глагол получает разные формы для разных смыслов.'), task('Представь, что друг звонит, пока ты работаешь. Скажи ему это одной короткой фразой.', 'I am working now.', 'Здесь нужен процесс в момент разговора.')])

unit('path-there-is', 'В комнате есть: there is и there are', 'Сообщить о наличии вещи в определённом месте.', [
 block('Сначала сообщаем, что вещь есть', 'There is a book — есть книга. Для нескольких предметов говорим there are: there are two books. Так вводим новые вещи в разговор. In the room значит «в комнате». Не переводим there отдельно как «там» в этой конструкции.', 'There is a book in the room.', 'В комнате есть книга.', task('Скажи «В комнате есть стул». chair = стул.', 'There is a chair in the room.', 'Один стул — there is a chair.'), task('Скажи «В комнате есть две книги».', 'There are two books in the room.', 'Несколько предметов — there are.')),
 block('Спросить о наличии', 'В вопросе is/are идут перед there: Is there a book? Утвердительный короткий ответ — Yes, there is. Отрицательный — No, there isn’t. Isn’t = is not.', 'Is there a chair?', 'Есть стул?', task('Спроси «Есть две книги?»', 'Are there two books?', 'Для двух книг используем Are there.'), task('Ответь «Да, есть» на вопрос Is there a chair?', 'Yes, there is.', 'В коротком ответе сохраняем there is.')),
 block('Есть книга или где эта книга?', 'There is a book in the room сообщает о новой книге. The book is in the room отвечает, где уже известная книга. Чтобы сказать, что одного предмета нет, можно использовать There isn’t a…', "There isn't a chair in the room.", 'В комнате нет стула.', task('Скажи, где уже известная книга: «Книга в комнате».', 'The book is in the room.', 'Книга уже известна, поэтому начинаем с The book.'), task('Скажи «В комнате нет телефона».', "There isn't a phone in the room.", 'Сообщаем об отсутствии: there isn’t a phone.'))
], [task('Придумай одну вещь в комнате. Напиши фразу с There is и знакомым словом.', 'There is a book in the room.', 'Можно выбрать другую знакомую вещь. Важно сообщить, что она есть.'), task('Спроси, есть ли стул в комнате, и ответь утвердительно.', 'Is there a chair in the room? Yes, there is.', 'Вопрос Is there, ответ there is.')])

unit('path-countability', 'Сколько: some, any, much и many', 'Говорить о количестве вещей и веществ.', [
 block('Книги считаем поштучно, воду — нет', 'Book → two books: можно посчитать отдельные предметы. Water (вода) обычно называем как вещество, без a и без -s. Some значит «немного» или «несколько»: some water, some books.', 'I have some water.', 'У меня есть немного воды.', task('Скажи «У меня есть несколько книг».', 'I have some books.', 'Some books — несколько книг.'), task('Скажи «У меня есть немного кофе».', 'I have some coffee.', 'Coffee здесь вещество/напиток вообще, без a и -s.')),
 block('Any в вопросах и отрицаниях', 'В обычном вопросе о наличии и в отрицании часто используем any. Do you have any water? — есть у тебя вода? I don’t have any water — у меня нет воды.', 'Do you have any books?', 'У тебя есть какие-нибудь книги?', task('Скажи «У меня нет воды».', "I don't have any water.", 'В этом отрицании используем any.'), task('Спроси, есть ли у человека кофе.', 'Do you have any coffee?', 'Обычный вопрос о наличии — any coffee.')),
 block('Many — сколько штук; much — сколько вещества', 'How many books? — сколько книг? How much water? — сколько воды? Для «много» в обычном утверждении удобно a lot of: a lot of books, a lot of water. A lot of — цельное сочетание.', 'How many books do you have?', 'Сколько у тебя книг?', task('Спроси «Сколько у тебя воды?»', 'How much water do you have?', 'Воду не считаем по отдельным штукам: how much.'), task('Скажи «У меня много книг».', 'I have a lot of books.', 'A lot of подходит для большого количества книг.'))
], [task('Спроси о количестве книг и количестве кофе. Два коротких вопроса.', 'How many books do you have? How much coffee do you have?', 'Many для книг, much для кофе.'), task('Напиши, что у тебя есть немного воды, но нет кофе. Можно двумя предложениями.', "I have some water. I don't have any coffee.", 'Some в утверждении, any в отрицании.')])

unit('path-place-time', 'In, on, at: где и когда', 'Назвать место и время с короткими готовыми сочетаниями.', [
 block('Где находится вещь', 'In — внутри: in the bag (в сумке). On — на поверхности: on the desk (на столе). At может показывать место как точку: at the door (у двери). Bag — сумка, desk — стол, door — дверь.', 'The book is in the bag.', 'Книга в сумке.', task('Скажи «Ручка на столе».', 'The pen is on the desk.', 'On показывает поверхность стола.'), task('Скажи «Он у двери».', 'He is at the door.', 'At the door — у двери.')),
 block('Когда: час, день, месяц', 'At five — в пять часов. On Monday — в понедельник. In May — в мае. Это три разные опоры: точное время — at, день — on, месяц — in.', 'I work on Monday.', 'Я работаю в понедельник.', task('Скажи «Я свободен в пять». free = свободен, five = пять.', 'I am free at five.', 'Перед точным временем ставим at.'), task('Скажи «Я работаю в мае». May = май.', 'I work in May.', 'Перед месяцем ставим in.')),
 block('Полезные целые сочетания', 'At home — дома, at work — на работе, in the morning — утром, at night — ночью. Эти сочетания лучше запомнить целиком: русский предлог не всегда помогает выбрать английский.', 'I am at home.', 'Я дома.', task('Скажи «Она на работе».', 'She is at work.', 'В at work не добавляем the.'), task('Скажи «Я читаю утром».', 'I read in the morning.', 'В этом сочетании нужна форма in the morning.'))
], [task('Скажи, где твоя книга: в сумке или на столе. Выбери один вариант.', 'My book is in the bag.', 'Место может отличаться; важно выбрать in или on по смыслу.'), task('Сообщи: «Я свободен в понедельник в пять».', 'I am free on Monday at five.', 'День — on Monday, время — at five.')])

unit('path-requests-can', 'Can: могу, умею, можно', 'Сказать об умении и попросить о простом действии.', [
 block('Can + действие', 'Can сообщает «могу» или «умею». После него глагол идёт без to и без -s. Swim — плавать; help — помогать. I can swim — я умею плавать. She can swim — она умеет плавать.', 'I can swim.', 'Я умею плавать.', task('Скажи «Она умеет плавать».', 'She can swim.', 'После can не добавляем -s к swim.'), task('Скажи «Я могу помочь». help = помочь.', 'I can help.', 'Can + help, без to.')),
 block('Can’t — не могу', 'Can’t — сокращение cannot. Для вопроса переставляем can перед человеком: Can you swim? Do не нужен. Короткий ответ: Yes, I can / No, I can’t.', "I can't swim.", 'Я не умею плавать.', task('Спроси «Ты умеешь плавать?»', 'Can you swim?', 'Can идёт перед you.'), task('Ответь отрицательно на Can you swim?', "No, I can't.", 'Короткий ответ сохраняет can’t.')),
 block('Просьба и разрешение', 'Can you help me, please? — можешь мне помочь, пожалуйста? Can I…? — можно мне…? Use — использовать, phone — телефон. Please смягчает просьбу.', 'Can I use your phone?', 'Можно воспользоваться твоим телефоном?', task('Попроси человека помочь тебе. Добавь please.', 'Can you help me, please?', 'You — человек, которого просишь; me — кому помочь.'), task('Попроси разрешения воспользоваться книгой. use your book = воспользоваться твоей книгой.', 'Can I use your book?', 'Can I — вопрос о разрешении для себя.'))
], [task('Напиши одно своё умение. Можно использовать read — читать, swim — плавать, help — помогать.', 'I can read.', 'После can сохраняем основную форму глагола.'), task('Спроси друга, может ли он помочь, и скажи, что сам сейчас помочь не можешь. now = сейчас.', "Can you help me? I can't help now.", 'Два смысла: просьба и отсутствие возможности.')])

unit('path-instructions', 'Как попросить сделать: Open the door', 'Дать короткую инструкцию и запрет.', [
 block('Начинаем с действия', 'Open — открой, close — закрой, read — прочитай. В инструкции можно сразу назвать действие: Open the door. You обычно не пишем — и так понятно, к кому обращаемся.', 'Open the door.', 'Открой дверь.', task('Попроси закрыть дверь. close = закрыть.', 'Close the door.', 'Начинаем с Close.'), task('Попроси прочитать книгу.', 'Read the book.', 'Read здесь означает просьбу/инструкцию.')),
 block('Don’t — не делай', 'Чтобы запретить действие, поставь don’t в начало. Don’t open the door — не открывай дверь. Please можно добавить в начале или в конце просьбы.', "Please don't close the door.", 'Пожалуйста, не закрывай дверь.', task('Скажи «Не открывай сумку». open the bag = открыть сумку.', "Don't open the bag.", 'Don’t перед действием делает запрет.'), task('Вежливо попроси открыть книгу, используя please.', 'Please open the book.', 'Please показывает вежливость; порядок остальных слов не меняется.')),
 block('Сначала и потом', 'First — сначала, then — затем. Можно дать две инструкции отдельными короткими предложениями. Не нужно соединять всё в длинную фразу.', 'First, open the book. Then, read.', 'Сначала открой книгу. Затем читай.', task('Дай две инструкции: сначала открой сумку, затем возьми книгу. take = взять.', 'First, open the bag. Then, take the book.', 'First и then показывают порядок действий.'), task('Поменяй просьбу Open the door на запрет.', "Don't open the door.", 'Добавляем don’t перед open.'))
], [task('Придумай одну вежливую просьбу со знакомыми open, close или read.', 'Please read the book.', 'Подходит любая понятная просьба с please и знакомым действием.'), task('Дай две инструкции: прочитай книгу, затем закрой её. it = её, когда речь о книге.', 'Read the book. Then, close it.', 'It помогает не повторять the book.')])

unit('path-adjectives-frequency', 'Какой и как часто', 'Описать предмет и привычку без длинных фраз.', [
 block('Какой предмет', 'Big — большой, small — маленький. Слово «какой» ставим перед названием: a small bag. Оно не меняется для нескольких предметов: small bags.', 'It is a small bag.', 'Это маленькая сумка.', task('Скажи «Это большая книга». big = большой.', 'It is a big book.', 'Big стоит перед book.'), task('Напиши «две маленькие сумки».', 'Two small bags.', 'Small остаётся без -s, множественное число у bags.')),
 block('Можно описать после is/are', 'Можно сначала назвать вещь: The bag is small. Small после is описывает сумку. Перед small здесь не нужен a: мы не называем новую вещь, а описываем известную.', 'The bag is small.', 'Сумка маленькая.', task('Скажи «Книги большие».', 'The books are big.', 'Books во множественном числе, поэтому are.'), task('Исправь: The book is a big.', 'The book is big.', 'После is здесь только описание big, без названия вещи; a убираем.')),
 block('Всегда, обычно, никогда', 'Always — всегда, usually — обычно, never — никогда. Перед действием: I usually read. После am/is/are: I am always ready. Never уже содержит отрицание: don’t не добавляем.', 'I usually read in the morning.', 'Я обычно читаю утром.', task('Скажи «Я никогда не пью кофе». drink = пить.', 'I never drink coffee.', 'Never перед drink; дополнительное don’t не нужно.'), task('Скажи «Она всегда готова».', 'She is always ready.', 'С be ставим always после is.'))
], [task('Опиши свою книгу или сумку одним предложением: big, small, red или blue.', 'My bag is small.', 'Описываем предмет после is.'), task('Напиши одну свою привычку с usually, always или never.', 'I usually read at home.', 'Для обычного действия ставь слово частоты перед глаголом.')])

unit('path-sound-basics', 'Как учиться слышать и произносить фразу', 'Слушать короткий образец, повторять и замечать одно различие.', [
 block('Буква и звук — не одно и то же', 'В английском написание не всегда подсказывает звук. Поэтому новое слово слушаем вместе с фразой. Нажми значок звука у примера, послушай, затем повтори. Не пытайся читать am русскими буквами.', 'I am ready.', 'Я готов.', task('Послушай пример I am ready. Затем закрой образец и напиши ту же мысль по памяти.', 'I am ready.', 'Сейчас тренируем связь звучания, смысла и записи, а не скорость.'), task('Послушай и произнеси You are ready. Затем запиши фразу по памяти.', 'You are ready.', 'С you нужна форма are — её тоже важно услышать.')),
 block('Выделяем важное слово', 'Обычно важное слово звучит заметнее. В I am READY можно выделить готовность. Послушай фразу целиком, повтори её спокойным темпом и не делай одинаково сильным каждое слово.', 'I am ready.', 'Я готов.', task('Скажи голосом, что ты готов. Затем проверь, какие слова распознались. Можно использовать I’m.', "I'm ready.", 'I’m ready и I am ready передают одну мысль. Расшифровка не оценивает качество звуков.'), task('Скажи «Я не готов», выделив голосом not. Сохрани расшифровку.', 'I am not ready.', 'Not меняет смысл. Проверка текста подтверждает слова, но не ударение.')),
 block('Повтори короткий кусочек', 'Не нужно повторять минутную запись целиком. Возьми 3–5 слов: послушай, сделай паузу, повтори, переслушай себя. Выбери одну вещь для улучшения, например чёткое not.', 'Are you ready?', 'Ты готов?', task('Произнеси вопрос Are you ready? Сохрани или напиши его расшифровку.', 'Are you ready?', 'Для вопроса are стоит перед you.'), task('Ответь на этот вопрос утвердительно короткой фразой. Yes = да.', 'Yes, I am.', 'Положительный короткий ответ заканчивается полной формой am.'))
], [task('Наговори две фразы: что ты готов, затем спроси друга, готов ли он.', 'I am ready. Are you ready?', 'Две знакомые конструкции помогают сосредоточиться на звучании.'), task('Напиши по-русски, что ты сравнил в своей записи с образцом. Достаточно одной конкретной мысли.', 'Я сравнил, слышно ли слово not.', 'Это наблюдение для себя. Автоматическая проверка не может выставить оценку звуку по тексту.')])

unit('path-past-simple', 'Что было вчера: I worked', 'Рассказать об одном законченном событии.', [
 block('Событие уже закончилось', 'Yesterday — вчера. Для законченного прошлого к обычному глаголу часто добавляем -ed: work → worked. Для live добавляем только -d: lived. Форма одинакова с I, you, she и they.', 'I worked yesterday.', 'Я работал вчера.', task('Скажи «Она работала вчера».', 'She worked yesterday.', 'В прошлом worked не меняется после she.'), task('Скажи «Я жил здесь». live → lived.', 'I lived here.', 'Lived показывает прошлое.')),
 block('Не все глаголы получают -ed', 'Некоторые формы нужно запоминать: go → went (идти/ехать), see → saw (видеть), have → had (иметь). У be свои формы: I/he/she/it was; you/we/they were.', 'I went home.', 'Я пошёл домой.', task('Скажи «Я видел Мию вчера». see → saw.', 'I saw Mia yesterday.', 'Saw — прошедшая форма see.'), task('Скажи «Мы были дома». we were = мы были; at home = дома.', 'We were at home.', 'С we прошедшая форма be — were.')),
 block('Did возвращает обычную форму', 'Для обычного действия в вопросе используем did, в отрицании — didn’t. После них глагол без -ed и без особой прошедшей формы: Did you go? I didn’t go. С was/were did не добавляем.', "I didn't work yesterday.", 'Я не работал вчера.', task('Спроси «Ты видел Мию?»', 'Did you see Mia?', 'После did возвращаем see, а не saw.'), task('Скажи «Она не пошла домой».', "She didn't go home.", 'После didn’t нужен go.'))
], [task('Придумай одно событие вчера с work, read или go. Для read прошедшая форма пишется read, но звучит /red/. Можно выбрать work.', 'I worked yesterday.', 'Важно одно законченное событие; сложная история пока не нужна.'), task('Спроси друга, работал ли он вчера, и скажи, что ты не работал.', "Did you work yesterday? I didn't work yesterday.", 'Did и didn’t уже указывают на прошлое.')])

unit('path-past-continuous', 'Что происходило в тот момент: I was reading', 'Показать процесс в определённый момент прошлого.', [
 block('Мысленно останавливаем прошлое', 'I read yesterday сообщает о факте. I was reading at five показывает, что в пять чтение шло. Для такого процесса нужны was/were + -ing: I was reading, they were reading.', 'I was reading at five.', 'В пять я читал.', task('Скажи «В пять она работала». at five = в пять.', 'She was working at five.', 'Was working показывает процесс в тот момент.'), task('Скажи «Мы читали в пять».', 'We were reading at five.', 'С we нужна форма were.')),
 block('Один процесс, другое событие', 'When значит «когда». I was reading when you called — я читал, когда ты позвонил. Чтение уже шло; звонок случился во время него. Call → called — позвонить → позвонил.', 'I was reading when you called.', 'Я читал, когда ты позвонил.', task('Скажи «Я работал, когда она позвонила».', 'I was working when she called.', 'Was working — процесс, called — событие.'), task('Скажи «Она читала, когда я пришёл домой». came home = пришёл домой.', 'She was reading when I came home.', 'Новое сочетание came home дано готовым; фон — was reading.')),
 block('Отрицание и вопрос', 'Was/were уже стоят перед -ing. Поставь not после них для отрицания; переставь их перед человеком для вопроса. Did в эту конструкцию не добавляем.', 'Were you reading?', 'Ты читал в тот момент?', task('Скажи «Я не работал в пять».', 'I was not working at five.', 'Not после was.'), task('Спроси «Она читала в пять?»', 'Was she reading at five?', 'В вопросе was перед she.'))
], [task('Опиши вымышленный момент вчера: что ты делал в пять? Одно предложение с was.', 'I was reading at five.', 'Выбери одно знакомое действие, которое шло в тот момент.'), task('Скажи, что ты читал, когда друг позвонил. Обратись к другу на you.', 'I was reading when you called.', 'Процесс и событие получают разные формы.')])

unit('path-future-simple', 'Will: решение сейчас, обещание, прогноз', 'Сказать о решении или предположении о будущем.', [
 block('Решаю прямо сейчас', 'Друг просит помощи, и ты отвечаешь I’ll help. I’ll = I will. Will + обычная форма глагола подходит для решения в момент разговора. Help не получает -s или to.', "I'll help you.", 'Я тебе помогу.', task('Ответь, что позвонишь другу. call you = позвонить тебе. Используй I’ll.', "I'll call you.", 'Решение сейчас можно выразить через I’ll.'), task('Скажи «Она поможет».', 'She will help.', 'Will одинаково для I, she и других лиц.')),
 block('Предположение о будущем', 'I think значит «я думаю». I think it will rain — думаю, будет дождь. Will подходит для прогноза или мнения; оно не означает, что говорящий точно знает будущее.', 'I think it will rain.', 'Думаю, будет дождь.', task('Скажи «Думаю, он будет готов». ready = готов.', 'I think he will be ready.', 'После will нужна be: will be ready.'), task('Скажи «Думаю, она поможет».', 'I think she will help.', 'Will help — твой прогноз.')),
 block('Won’t и вопросы', 'Won’t = will not. I won’t work tomorrow — я не буду работать завтра. Tomorrow — завтра. В вопросе will перед человеком: Will you help?', "I won't work tomorrow.", 'Я не буду работать завтра.', task('Спроси «Ты поможешь?»', 'Will you help?', 'Will в начале вопроса.'), task('Обещай «Я не буду опаздывать». be late = опаздывать.', "I won't be late.", 'Won’t be late выражает обещание не опоздать.'))
], [task('Друг не понимает задание. Ответь одним предложением, что ты поможешь.', "I'll help you.", 'Решение помочь принимается сейчас.'), task('Напиши один прогноз, начиная с I think. Используй will be ready или will rain.', 'I think it will rain.', 'Нужен прогноз, а не длинное обоснование.')])

unit('path-future-plans', 'План и договорённость: going to и meeting', 'Различать намерение, договорённость и расписание.', [
 block('Уже решил заранее', 'I am going to read — я собираюсь читать. Схема: am/is/are + going to + действие. Здесь going to передаёт намерение, а не движение куда-то.', 'I am going to read tonight.', 'Я собираюсь читать сегодня вечером.', task('Скажи «Я собираюсь работать завтра». tomorrow = завтра.', 'I am going to work tomorrow.', 'Решение уже принято: am going to work.'), task('Скажи «Она собирается позвонить».', 'She is going to call.', 'С she нужна форма is перед going to.')),
 block('Уже договорились', 'Present continuous можно использовать для договорённости на будущее, если время понятно. I am meeting Mia tomorrow — я встречаюсь с Мией завтра. Meet — встретиться. Контекст отличает это от процесса прямо сейчас.', 'I am meeting Mia tomorrow.', 'Завтра я встречаюсь с Мией.', task('Скажи «Мы встречаемся завтра».', 'We are meeting tomorrow.', 'Are meeting + tomorrow указывает на договорённость.'), task('Спроси «Ты завтра работаешь?» Речь об уже согласованном графике.', 'Are you working tomorrow?', 'Вопрос о договорённом плане можно задать через continuous.')),
 block('Расписание', 'Для расписания часто подходит present simple: The train leaves at five — поезд отправляется в пять. Train — поезд, leave — отправляться. Это установленное время, а не решение поезда.', 'The train leaves at five.', 'Поезд отправляется в пять.', task('Скажи «Занятие начинается в пять». class = занятие, start = начинаться.', 'The class starts at five.', 'Расписание: starts.'), task('Друг просит помочь, и ты только сейчас решаешь согласиться. Ответь с will.', "I'll help you.", 'Это решение сейчас; going to здесь не требуется.'))
], [task('Напиши одно заранее принятое намерение на завтра с going to.', 'I am going to read tomorrow.', 'Выбери знакомое действие и назови свой план.'), task('Напиши две короткие фразы: намерение читать завтра и договорённость встретиться с Мией завтра.', 'I am going to read tomorrow. I am meeting Mia tomorrow.', 'Намерение и договорённость можно выразить разными конструкциями.')])

unit('path-present-perfect', 'Уже сделал: прошлое связано с настоящим', 'Сообщить о результате сейчас и отличить его от события вчера.', [
 block('Смотрим на результат сейчас', 'I have finished — я закончил, и это важно сейчас. Схема: have/has + третья форма глагола. У обычных глаголов это -ed: finish → finished. Finish — закончить. Have здесь помогает построить время, а не значит «иметь».', 'I have finished.', 'Я закончил.', task('Скажи «Она закончила». Используй has.', 'She has finished.', 'С she используется has.'), task('Скажи «Я открыл дверь». Важно, что она теперь открыта. open → opened.', 'I have opened the door.', 'Смотрим на результат сейчас: have opened.')),
 block('Опыт: ever и never', 'У некоторых глаголов третья форма особая: see → seen, be → been. Ever — когда-нибудь; never — никогда. Have you been there? — ты там бывал? There здесь означает «там».', 'Have you ever been there?', 'Ты когда-нибудь там бывал?', task('Скажи «Я никогда там не был».', 'I have never been there.', 'Never уже выражает отрицание; been — форма be.'), task('Спроси «Ты видел эту книгу?» Используй seen и the book.', 'Have you seen the book?', 'Вопрос начинается с have, после you ставим seen.')),
 block('Yesterday требует другой взгляд', 'Отрицание: have not → haven’t, has not → hasn’t. Если называем законченное время — yesterday, last week (на прошлой неделе) — обычно нужен past simple: I finished yesterday. В американской речи past simple также часто встречается с just/already; не считай его автоматически ошибкой.', 'I finished yesterday.', 'Я закончил вчера.', task('Скажи «Она закончила вчера».', 'She finished yesterday.', 'Вчера — законченное прошлое, поэтому finished без has.'), task('Скажи «Я ещё не закончил». yet = ещё, в конце отрицания.', "I haven't finished yet.", 'Haven’t = have not. Yet стоит в конце.'))
], [task('Ты закончил работу и теперь свободен. Сообщи о завершении одной фразой с have.', 'I have finished.', 'Результат важен сейчас.'), task('Передай два смысла: «Я никогда там не был» и «Я работал вчера».', 'I have never been there. I worked yesterday.', 'Опыт до настоящего момента и событие вчера выражены по-разному.')])

unit('path-comparatives', 'Больше, лучше, достаточно', 'Сравнить два предмета и объяснить простую оценку.', [
 block('Сравниваем два предмета', 'Small → smaller (меньше), big → bigger (больше). Than — чем. This bag значит «эта сумка», that bag — «та сумка». This bag is smaller than that bag.', 'This bag is smaller than that bag.', 'Эта сумка меньше той.', task('Скажи «Эта книга больше той книги».', 'This book is bigger than that book.', 'В bigger удваиваем g; than связывает два предмета.'), task('Скажи «Моя сумка меньше твоей сумки».', 'My bag is smaller than your bag.', 'Smaller + than — меньше, чем.')),
 block('Длинные слова и особые формы', 'Expensive — дорогой. Обычно говорим more expensive, а не expensive-er. Good → better — хороший → лучше. Для «самый» в группе: the biggest, the most expensive, the best.', 'This phone is more expensive.', 'Этот телефон дороже.', task('Скажи «Эта книга лучше». good → better.', 'This book is better.', 'Better — особая сравнительная форма good.'), task('Скажи «Это самая большая сумка».', 'It is the biggest bag.', 'Самая большая среди группы — the biggest.')),
 block('Too и enough', 'Too big — слишком большой: это мешает. Big enough — достаточно большой: размера хватает. Enough после описания, too перед ним. Small enough — достаточно маленький.', 'The bag is too big.', 'Сумка слишком большая.', task('Скажи «Сумка достаточно большая».', 'The bag is big enough.', 'Enough после big.'), task('Скажи «Телефон слишком дорогой».', 'The phone is too expensive.', 'Too сообщает, что цена чрезмерна для ситуации.'))
], [task('Сравни две книги или две сумки по размеру одним предложением.', 'This book is smaller than that book.', 'Важно назвать оба предмета и использовать than.'), task('Скажи, что сумка слишком маленькая и тебе нужна сумка побольше. need = нуждаться/нужна, a bigger bag = сумка побольше.', 'The bag is too small. I need a bigger bag.', 'Два коротких предложения: проблема и нужный вариант.')])

unit('path-past-habits', 'Раньше было так: used to', 'Сравнить прежнюю привычку с настоящим.', [
 block('Было обычно, теперь изменилось', 'Used to + действие говорит о прежней привычке или состоянии. I used to live here — раньше я жил здесь; теперь это не так. После to используем live, не lived.', 'I used to live here.', 'Раньше я жил здесь.', task('Скажи «Раньше я работал здесь».', 'I used to work here.', 'Used to показывает прежнюю обычную ситуацию.'), task('Скажи «Раньше она пила кофе». drink = пить.', 'She used to drink coffee.', 'Форма used to не меняется после she.')),
 block('Не путать с одним событием', 'I called yesterday — один звонок вчера. I used to call every day — раньше звонил каждый день. Used to не нужно для одиночного завершённого случая.', 'I used to call every day.', 'Раньше я звонил каждый день.', task('Скажи об одном событии: «Я позвонил вчера».', 'I called yesterday.', 'Для одного звонка вчера нужен past simple.'), task('Скажи о прежней привычке: «Раньше я читал утром».', 'I used to read in the morning.', 'Повторяющаяся привычка прошлого — used to.')),
 block('Вопрос и отрицание', 'После did/didn’t пишем use to, без -d: Did you use to live here? I didn’t use to live here. Не путай с be used to — это другая тема про привычность, сейчас её не используем.', "I didn't use to drink coffee.", 'Раньше я не пил кофе.', task('Спроси «Ты раньше работал здесь?»', 'Did you use to work here?', 'После did нужна форма use.'), task('Скажи «Она раньше здесь не жила».', "She didn't use to live here.", 'Didn’t use to + live.'))
], [task('Придумай прежнюю привычку с read, work или drink. Одна фраза с used to.', 'I used to read at night.', 'Важно, что привычка относится к прошлому и изменилась.'), task('Сравни: раньше ты пил кофе, теперь пьёшь чай. now = теперь.', 'I used to drink coffee. Now I drink tea.', 'Прежняя привычка — used to, нынешняя — present simple.')])

unit('path-obligation', 'Нужно, стоит, нельзя: have to, should, mustn’t', 'Отличать обязанность, совет, запрет и отсутствие необходимости.', [
 block('Have to — нужно по обстоятельствам', 'I have to work — мне нужно работать. She has to work — ей нужно работать. Это обязанность или необходимость. Must тоже может выражать сильную необходимость: I must go — мне пора идти.', 'I have to work tomorrow.', 'Завтра мне нужно работать.', task('Скажи «Ей нужно позвонить».', 'She has to call.', 'С she нужна форма has to.'), task('Спроси «Тебе нужно работать завтра?»', 'Do you have to work tomorrow?', 'Вопрос с have to строится через do.')),
 block('Should — стоит, советую', 'Should + действие выражает совет, а не обязательное правило. Rest — отдыхать. You should rest — тебе стоит отдохнуть. Shouldn’t — не стоит.', 'You should rest.', 'Тебе стоит отдохнуть.', task('Посоветуй другу позвонить Мие.', 'You should call Mia.', 'Should call — совет позвонить.'), task('Посоветуй не работать ночью.', "You shouldn't work at night.", 'Shouldn’t — отрицательный совет.')),
 block('Не нужно — не то же, что нельзя', 'Don’t have to — нет необходимости, но можно. Mustn’t — нельзя, запрещено. Wait — ждать; touch — трогать. You don’t have to wait — ждать не обязательно. You mustn’t touch it — это трогать нельзя.', "You don't have to wait.", 'Ждать не обязательно.', task('Запрети трогать предмет. Используй mustn’t touch it.', "You mustn't touch it.", 'Mustn’t выражает запрет.'), task('Скажи, что завтра работать не обязательно.', "You don't have to work tomorrow.", 'Это отсутствие обязанности, а не запрет работать.'))
], [task('Дай уставшему другу один совет с should.', 'You should rest.', 'Совет можно принять или не принять; это не обязанность.'), task('Напиши две разные мысли: ждать не обязательно; трогать предмет нельзя.', "You don't have to wait. You mustn't touch it.", 'Don’t have to и mustn’t передают разные смыслы.')])

unit('path-zero-first', 'Если: правило и возможное будущее', 'Связать условие с результатом.', [
 block('If — если', 'If вводит условие. Для привычного результата можно использовать present simple в обеих частях. If I am tired, I rest — если я устаю, то отдыхаю. Вторая часть показывает результат.', 'If I am tired, I rest.', 'Если я устаю, я отдыхаю.', task('Скажи «Если я свободен, я читаю». free = свободен.', 'If I am free, I read.', 'Обычная привычка: present simple в обеих частях.'), task('Скажи «Если она устала, она отдыхает».', 'If she is tired, she rests.', 'С she: is в условии, rests в результате.')),
 block('Возможное событие впереди', 'Если речь о возможном будущем, после if обычно present simple, а в результате will. If I am free, I will call — если буду свободен, позвоню. Русское «буду» после «если» не требует will после if.', 'If I am free, I will call.', 'Если я буду свободен, я позвоню.', task('Скажи «Если я буду дома, я помогу». at home = дома.', 'If I am at home, I will help.', 'После if: am; результат: will help.'), task('Скажи «Если она позвонит, я помогу».', 'If she calls, I will help.', 'Calls после if относится к будущему без will.')),
 block('Порядок частей', 'Можно начать с результата: I will call if I am free. Смысл тот же. Когда if стоит в начале, обычно ставим запятую между частями. Не делай из возможности обещание без условия.', 'I will call if I am free.', 'Я позвоню, если буду свободен.', task('Начни с результата: «Я помогу, если буду дома».', 'I will help if I am at home.', 'Условие можно поставить после результата.'), task('Исправь: If I will be free, I will call.', 'If I am free, I will call.', 'В обычном условии о будущем после if используем am.'))
], [task('Напиши одно возможное условие для звонка: свободен или дома.', 'If I am at home, I will call.', 'Нужно условие с if и результат с will.'), task('Напиши свою обычную реакцию на усталость: отдыхаешь или читаешь. Начни с If.', 'If I am tired, I rest.', 'Это повторяющийся порядок событий, не один прогноз.')])

unit('path-gerund-infinitive', 'Want to read, enjoy reading: два действия рядом', 'Запоминать действие вместе с подходящим продолжением.', [
 block('Want to — хочу сделать', 'Если после want нужно второе действие, ставим to: I want to read. Want — хотеть, need — нуждаться; I need to work — мне нужно работать. После to основной глагол не меняется.', 'I want to read.', 'Я хочу читать.', task('Скажи «Я хочу позвонить».', 'I want to call.', 'Want + to call.'), task('Скажи «Ей нужно работать». Используй needs to.', 'She needs to work.', 'У needs окончание -s, но work после to не меняется.')),
 block('Enjoy + -ing', 'Enjoy — получать удовольствие. После enjoy второе действие имеет -ing: I enjoy reading. Это не процесс сейчас: перед reading здесь нет am. Форма зависит от слова enjoy.', 'I enjoy reading.', 'Мне нравится читать.', task('Скажи «Мне нравится плавать». swim → swimming.', 'I enjoy swimming.', 'После enjoy нужна форма swimming.'), task('Исправь: I enjoy to read.', 'I enjoy reading.', 'Модель enjoy + -ing, без to.')),
 block('После can — без to; для цели — to', 'После can второй глагол без to: I can read. А отдельное to может отвечать «зачем?»: I am here to help — я здесь, чтобы помочь. Запоминай небольшие сочетания, а не правило «после любого глагола to».', 'I am here to help.', 'Я здесь, чтобы помочь.', task('Исправь: I can to swim.', 'I can swim.', 'После can сразу основной глагол.'), task('Скажи «Я здесь, чтобы читать».', 'I am here to read.', 'To read объясняет цель.'))
], [task('Напиши два предложения: что ты хочешь сделать и что тебе нравится делать. Используй want и enjoy.', 'I want to read. I enjoy swimming.', 'Want to + действие; enjoy + -ing.'), task('Объясни одной английской фразой, что ты здесь, чтобы помочь.', 'I am here to help.', 'To help отвечает на вопрос «зачем здесь?».')])

unit('path-relative-basic', 'Который: уточняем человека или вещь', 'Помочь собеседнику понять, о ком или о чём речь.', [
 block('Who — о человеке', 'The person who works here — человек, который здесь работает. Person — человек. Who связывает человека с действием и помогает выбрать нужного человека среди других.', 'The person who works here is Mia.', 'Человек, который здесь работает, — Мия.', task('Скажи «Человек, который живёт здесь, — Алекс».', 'The person who lives here is Alex.', 'Who заменяет повторное название человека.'), task('Скажи «Я знаю человека, который работает здесь».', 'I know the person who works here.', 'Часть who works here уточняет человека.')),
 block('That или which — о вещи', 'Для вещи можно использовать that или which: the book that is on the desk — книга, которая на столе. Здесь это нужное уточнение, поэтому запятые не добавляем.', 'The book that is on the desk is mine.', 'Книга на столе — моя.', task('Скажи «Книга, которая в сумке, красная».', 'The book that is in the bag is red.', 'That связывает книгу с уточнением места. Which здесь тоже возможно.'), task('Скажи «Телефон, который на столе, мой». mine = мой, без названия вещи после него.', 'The phone that is on the desk is mine.', 'Mine — самостоятельное «мой»; my требует название вещи.')),
 block('Не повторяем he/it', 'В The person who works here слово who уже выполняет работу «он/она». Поэтому who he works here не нужно. То же с вещью: the book that is red, не that it is red.', 'I know the person who lives here.', 'Я знаю человека, который здесь живёт.', task('Исправь: I know the person who he works here.', 'I know the person who works here.', 'He лишнее: его место уже занимает who.'), task('Исправь: The book that it is in the bag is red.', 'The book that is in the bag is red.', 'It после that здесь лишнее.'))
], [task('Уточни, кого ты знаешь: человека, который живёт здесь. Одно предложение.', 'I know the person who lives here.', 'Уточнение who lives here помогает определить человека.'), task('Назови цвет книги, которая на столе. Выбери red или blue.', 'The book that is on the desk is blue.', 'Сначала выбираем нужную книгу, затем сообщаем цвет.')])

unit('path-connectors-basic', 'Because, so, but, although: связываем мысли', 'Показать причину, результат или противопоставление.', [
 block('Because — потому что', 'Because вводит причину: I am resting because I am tired — я отдыхаю, потому что устал. Сначала сообщение, затем объяснение «почему». Resting — отдыхаю сейчас.', 'I am resting because I am tired.', 'Я отдыхаю, потому что устал.', task('Скажи «Я дома, потому что устал».', 'I am at home because I am tired.', 'После because идёт причина.'), task('Скажи «Я читаю, потому что мне нравится эта книга». like the book = нравится эта книга.', 'I am reading because I like the book.', 'Часть после because отвечает «почему читаю».')),
 block('So — поэтому; but — но', 'So вводит результат: I am tired, so I am resting. But показывает контраст: I am tired, but I am working. Не ставь because и so сразу для одной причины и результата.', 'I am tired, so I am resting.', 'Я устал, поэтому отдыхаю.', task('Скажи «Я свободен, поэтому могу помочь».', 'I am free, so I can help.', 'После so идёт следствие.'), task('Скажи «Я устал, но работаю».', 'I am tired, but I am working.', 'But показывает, что результат отличается от ожидаемого.')),
 block('Although — хотя', 'Although I am tired, I am working — хотя я устал, я работаю. Although уже показывает контраст, поэтому дополнительное but перед второй частью не нужно.', 'Although I am tired, I am working.', 'Хотя я устал, я работаю.', task('Скажи «Хотя я занят, я могу помочь». busy = занят.', 'Although I am busy, I can help.', 'Контраст уже выражен although.'), task('Исправь: Although I am tired, but I am reading.', 'Although I am tired, I am reading.', 'Убираем but: although уже соединяет эти мысли.'))
], [task('Напиши две мысли о себе и соедини их because или so. Можно придумать ситуацию.', 'I am at home because I am tired.', 'Выбери порядок: сообщение + because + причина или причина + so + результат.'), task('Скажи, что ты занят, но можешь помочь. Используй but.', 'I am busy, but I can help.', 'But подходит для противопоставления.')])

unit('path-everyday-phrasal', 'Get up, turn off, look for: учим сочетание целиком', 'Использовать три частых сочетания в бытовой ситуации.', [
 block('Get up — встать с постели', 'Два слова могут вместе передавать один смысл. Get up — встать с постели. Не переводи get отдельно как «получить». I get up at seven — я встаю в семь. Seven — семь.', 'I get up at seven.', 'Я встаю в семь.', task('Скажи «Она встаёт в семь».', 'She gets up at seven.', 'Меняется глагол get → gets, up остаётся.'), task('Спроси «Ты встаёшь в пять?»', 'Do you get up at five?', 'В вопросе после do — get up.')),
 block('Turn off — выключить', 'Turn off the light — выключи свет. Light — свет. Название вещи можно поставить в середину: turn the light off. Если заменяешь вещь словом it, оно идёт только в середину: turn it off.', 'Turn off the light.', 'Выключи свет.', task('Попроси выключить свет, заменив the light на it.', 'Turn it off.', 'С it используем порядок turn it off.'), task('Попроси не выключать свет.', "Don't turn off the light.", 'Don’t перед всем сочетанием turn off.')),
 block('Look for — искать', 'I am looking for my phone — я ищу телефон. Look for не означает просто «смотреть»: всё сочетание значит «искать». Его части не разделяем предметом: look for it.', 'I am looking for my phone.', 'Я ищу свой телефон.', task('Скажи «Она ищет свою книгу». her book = её книга.', 'She is looking for her book.', 'Процесс сейчас: is looking for.'), task('Замени my phone словом it: I am looking for my phone.', 'I am looking for it.', 'It остаётся после for.'))
], [task('Напиши время, когда ты обычно встаёшь. Можно использовать five или seven.', 'I get up at seven.', 'Сочетание get up используем как одно действие.'), task('Ты не находишь телефон. Сообщи, что ищешь его, одной фразой.', 'I am looking for my phone.', 'Looking for передаёт поиск прямо сейчас.')])

unit('path-listening-routine', 'Короткое сообщение: кто, когда и что изменилось', 'Выделить нужные детали и уточнить непонятое.', [
 block('Сначала одна деталь', 'Прослушай пример кнопкой звука, не читай его одновременно. Найди только время. Meeting — встреча; at five — в пять. Не нужно узнавать каждое слово с первого прослушивания.', 'The meeting is at five.', 'Встреча в пять.', task('Прослушай пример ещё раз. Ответь по-английски, во сколько встреча. Начни с The meeting is.', 'The meeting is at five.', 'Сейчас нужна одна точная деталь: at five.'), task('Напиши уточнение «В пять?» одним коротким вопросом.', 'At five?', 'В разговоре можно переспросить коротко, без длинного предложения.')),
 block('Поправка важнее первого числа', 'В сообщении могут сначала назвать одно время, потом исправить его. Послушай: The meeting is at five. Sorry, at seven. Sorry — извини. Итоговое время — то, которым исправили первое.', 'The meeting is at five. Sorry, at seven.', 'Встреча в пять. Извини, в семь.', task('Прослушай пример и запиши только актуальное время встречи целым коротким предложением.', 'The meeting is at seven.', 'Поздняя поправка at seven заменяет первое время.'), task('Попроси повторить: «Можешь повторить это, пожалуйста?» Готовая опора: say that again = повторить это.', 'Can you say that again, please?', 'Это полезная готовая просьба, если не удалось расслышать.')),
 block('Подтверждаем договорённость', 'So — значит/итак в начале подтверждения. Tomorrow — завтра. Можно повторить услышанное: So, the meeting is at seven tomorrow? Это даёт человеку возможность тебя исправить.', 'So, the meeting is at seven tomorrow?', 'Значит, встреча завтра в семь?', task('Прослушай пример и ответь утвердительно. Yes = да; that’s right = всё верно.', "Yes, that's right.", 'Короткое подтверждение достаточно.'), task('Нужно исправить время на пять. Напиши «Нет, в пять».', 'No, at five.', 'Короткая поправка сохраняет фокус на времени.'))
], [task('Прослушай последнюю фразу без текста и запиши время и день по памяти.', 'At seven tomorrow.', 'Проверь после своей попытки. Печатное задание не измеряет слух без реального прослушивания.'), task('Представь, что ты не расслышал время. Попроси повторить, используя знакомую фразу.', 'Can you say that again, please?', 'Уточнение полезнее случайной догадки.')])

unit('path-email-basic', 'Первое короткое сообщение', 'Написать адресату 3–4 понятные фразы с одной целью.', [
 block('Приветствие и цель', 'Для знакомого человека подходит Hi, Mia. Дальше сразу скажи главное. Can you help me? — можешь помочь? Не нужно начинать с длинного вступления.', 'Hi, Mia. Can you help me?', 'Привет, Мия. Можешь мне помочь?', task('Поздоровайся с Алексом и спроси, свободен ли он завтра. tomorrow = завтра.', 'Hi, Alex. Are you free tomorrow?', 'Короткое приветствие и один понятный вопрос.'), task('Поздоровайся с Мией и попроси позвонить тебе. Can you call me? = можешь мне позвонить?', 'Hi, Mia. Can you call me?', 'Адресат сразу видит просьбу.')),
 block('Одна нужная деталь', 'Добавь только то, что помогает ответить: I am free at five — я свободен в пять. Или короткую причину с because. Каждая фраза должна помогать цели сообщения.', 'I am free at five.', 'Я свободен в пять.', task('Добавь деталь: «Я дома завтра».', 'I am at home tomorrow.', 'Эта деталь помогает договориться о звонке или встрече.'), task('Добавь причину просьбы: «Мне нужна помощь, потому что я не понимаю это». need help = нужна помощь, understand it = понимать это.', "I need help because I don't understand it.", 'Причина объясняет, зачем пишешь. Все новые сочетания даны в задании.')),
 block('Завершаем понятно', 'Thanks — спасибо. Можно закончить сообщением, чего ждёшь: Please call me — пожалуйста, позвони мне. Для знакомого достаточно короткого завершения; официальный стиль будем учить позже.', 'Please call me. Thanks!', 'Пожалуйста, позвони мне. Спасибо!', task('Поблагодари человека одним словом по-английски.', 'Thanks!', 'В коротком личном сообщении этого достаточно.'), task('Напиши одну заключительную просьбу: «Пожалуйста, позвони мне завтра».', 'Please call me tomorrow.', 'В просьбе есть действие и время.'))
], [task('Напиши Алексу короткое сообщение: поздоровайся, спроси, свободен ли он завтра, скажи, что ты свободен в пять, поблагодари. Четыре короткие фразы.', 'Hi, Alex. Are you free tomorrow? I am free at five. Thanks!', 'Здесь используются только уже отработанные части сообщения.'), task('Теперь напиши Мие с другой целью: попроси позвонить тебе завтра и поблагодари. Достаточно трёх коротких фраз.', 'Hi, Mia. Can you call me tomorrow? Thanks!', 'Сохраняем структуру, но меняем адресата и цель.')])

ORDER_A1 = ['path-be', 'path-articles-basic', 'path-plurals', 'path-present-simple', 'path-pronouns', 'path-possession', 'path-questions-basic', 'path-present-continuous', 'path-there-is', 'path-countability', 'path-place-time', 'path-requests-can', 'path-instructions', 'path-adjectives-frequency', 'path-sound-basics']
ORDER_A2 = [row[0] for row in LESSONS if row[0] not in ORDER_A1]

def build():
    lessons = json.loads(COURSE.read_text('utf-8'))
    previous = {l['id']: l for l in lessons}
    for id, title, goal, blocks, independent in LESSONS:
        lesson = previous[id]
        lesson.update(title=title, subtitle='Короткое объяснение → пример → твоя попытка', goal=goal, beginner=True, minutes=25)
        order = ORDER_A1 if lesson['level'] == 'A1' else ORDER_A2
        position = order.index(id)
        lesson['prerequisites'] = [order[position-1]] if position else ([] if lesson['level']=='A1' else [ORDER_A1[-1]])
        lesson['sections'] = [{'title':b[0], 'body':b[1]} for b in blocks]
        lesson['examples'] = [{'en':b[2], 'ru':b[3], 'why':b[1]} for b in blocks]
        lesson['formula'] = ' → '.join(b[2] for b in blocks[:2])
        old = {e['id']:e for e in lesson['exercises']}
        exercises=[]
        for title_, body, en, ru, tasks in blocks:
            for prompt, answer, why in tasks:
                exercises.append({'kind':'translate','prompt':prompt,'context':'Одна небольшая задача. Напиши или надиктуй свой ответ.', 'answers':[answer], 'hint':body, 'explanation':why, 'practiceStage':'guided', 'guidance':{'title':title_, 'body':body,'example':en,'translation':ru}})
        for prompt,answer,why in independent:
            exercises.append({'kind':'write','prompt':prompt,'context':'Попробуй без образца. Если трудно, вернись к объяснению — это нормально.', 'answers':[answer],'hint':goal,'explanation':why,'practiceStage':'independent'})
        for i,e in enumerate(exercises,1):
            eid=f'e{i}';e['id']=eid
            prior=old.get(eid)
            e['revision']=max(1,(prior or {}).get('revision',0))
            if prior and any(prior.get(k)!=v for k,v in e.items() if k not in ('id','revision')):
                e['revision']=prior.get('revision',0)+1
        lesson['exercises']=exercises
    write_json(COURSE,lessons)
    path=ROOT/'content/learning-path.json';data=json.loads(path.read_text('utf-8'))
    for section in data['levels']:
        order=ORDER_A1 if section['id']=='A1' else ORDER_A2 if section['id']=='A2' else None
        if order:
            section['title'] = 'С нуля: первые фразы' if section['id']=='A1' else 'Простые разговоры и сообщения'
            section['lessonIds']=order+[id for id in section['lessonIds'] if id not in order]
            section['diagnostic']='Начни с коротких шагов. Если тема знакома, открой последние два задания «Теперь сам». По ним станет понятно, нужна ли тренировка.'
    write_json(path,data)
    # The old evidence IDs pointed at different, longer tasks. Keep only the
    # new independent work; remove claims these short drills no longer support.
    path=ROOT/'content/curriculum-mastery-map.json';data=json.loads(path.read_text('utf-8'))
    changed={row[0] for row in LESSONS}
    for level in data['levels']:
        for indicator in level['indicators']:
            evidence=[]
            for item in indicator['evidence']:
                id=item.get('lessonId')
                if id in changed:
                    if indicator['id'] in ('a1-speaking-day','a1-phonology-clarity'):
                        continue
                    independent=[e for e in previous[id]['exercises'] if e['practiceStage']=='independent']
                    item.update(exerciseIds=[e['id'] for e in independent],note='Самостоятельные короткие задания после подготовки: '+' / '.join(e['prompt'] for e in independent))
                evidence.append(item)
            indicator['evidence']=evidence
    data['beginnerEvidenceUpdatedAt']='2026-09-20'
    for snapshot in data['snapshotFiles']:
        if snapshot['file']=='app/content/courses/foundation.json':
            snapshot['sha256']=hashlib.sha256(COURSE.read_bytes()).hexdigest()
    write_json(path,data)
    print(f'Rebuilt {len(LESSONS)} lessons, {sum(len(previous[id]["exercises"]) for id,*_ in LESSONS)} steps. Learner data untouched.')

if __name__ == '__main__':
    build()
